func (v ChecksValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var active basetypes.ObjectValue

	if v.Active.IsNull() {
		active = types.ObjectNull(
			ActiveValue{}.AttributeTypes(ctx),
		)
	}

	if v.Active.IsUnknown() {
		active = types.ObjectUnknown(
			ActiveValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Active.IsNull() && !v.Active.IsUnknown() {
		active = types.ObjectValueMust(
			ActiveValue{}.AttributeTypes(ctx),
			v.Active.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"active": basetypes.ObjectType{
			AttrTypes: ActiveValue{}.AttributeTypes(ctx),
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"active": active,
		})

	return objVal, diags
}

