func (v ActiveValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var healthy basetypes.ObjectValue

	if v.Healthy.IsNull() {
		healthy = types.ObjectNull(
			HealthyValue{}.AttributeTypes(ctx),
		)
	}

	if v.Healthy.IsUnknown() {
		healthy = types.ObjectUnknown(
			HealthyValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Healthy.IsNull() && !v.Healthy.IsUnknown() {
		healthy = types.ObjectValueMust(
			HealthyValue{}.AttributeTypes(ctx),
			v.Healthy.Attributes(),
		)
	}

	var unhealthy basetypes.ObjectValue

	if v.Unhealthy.IsNull() {
		unhealthy = types.ObjectNull(
			UnhealthyValue{}.AttributeTypes(ctx),
		)
	}

	if v.Unhealthy.IsUnknown() {
		unhealthy = types.ObjectUnknown(
			UnhealthyValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Unhealthy.IsNull() && !v.Unhealthy.IsUnknown() {
		unhealthy = types.ObjectValueMust(
			UnhealthyValue{}.AttributeTypes(ctx),
			v.Unhealthy.Attributes(),
		)
	}

	var reqHeadersVal basetypes.ListValue
	switch {
	case v.ReqHeaders.IsUnknown():
		reqHeadersVal = types.ListUnknown(types.StringType)
	case v.ReqHeaders.IsNull():
		reqHeadersVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		reqHeadersVal, d = types.ListValue(types.StringType, v.ReqHeaders.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"concurrency": basetypes.Int64Type{},
			"healthy": basetypes.ObjectType{
				AttrTypes: HealthyValue{}.AttributeTypes(ctx),
			},
			"host":                     basetypes.StringType{},
			"http_path":                basetypes.StringType{},
			"https_verify_certificate": basetypes.BoolType{},
			"port":                     basetypes.Int64Type{},
			"req_headers": basetypes.ListType{
				ElemType: types.StringType,
			},
			"timeout": basetypes.Float64Type{},
			"type":    basetypes.StringType{},
			"unhealthy": basetypes.ObjectType{
				AttrTypes: UnhealthyValue{}.AttributeTypes(ctx),
			},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"concurrency": basetypes.Int64Type{},
		"healthy": basetypes.ObjectType{
			AttrTypes: HealthyValue{}.AttributeTypes(ctx),
		},
		"host":                     basetypes.StringType{},
		"http_path":                basetypes.StringType{},
		"https_verify_certificate": basetypes.BoolType{},
		"port":                     basetypes.Int64Type{},
		"req_headers": basetypes.ListType{
			ElemType: types.StringType,
		},
		"timeout": basetypes.Float64Type{},
		"type":    basetypes.StringType{},
		"unhealthy": basetypes.ObjectType{
			AttrTypes: UnhealthyValue{}.AttributeTypes(ctx),
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"concurrency":              v.Concurrency,
			"healthy":                  healthy,
			"host":                     v.Host,
			"http_path":                v.HttpPath,
			"https_verify_certificate": v.HttpsVerifyCertificate,
			"port":                     v.Port,
			"req_headers":              reqHeadersVal,
			"timeout":                  v.Timeout,
			"type":                     v.ActiveType,
			"unhealthy":                unhealthy,
		})

	return objVal, diags
}

func (v ActiveValue) Equal(o attr.Value) bool {
	other, ok := o.(ActiveValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Concurrency.Equal(other.Concurrency) {
		return false
	}

	if !v.Healthy.Equal(other.Healthy) {
		return false
	}

	if !v.Host.Equal(other.Host) {
		return false
	}

	if !v.HttpPath.Equal(other.HttpPath) {
		return false
	}

	if !v.HttpsVerifyCertificate.Equal(other.HttpsVerifyCertificate) {
		return false
	}

	if !v.Port.Equal(other.Port) {
		return false
	}

	if !v.ReqHeaders.Equal(other.ReqHeaders) {
		return false
	}

	if !v.Timeout.Equal(other.Timeout) {
		return false
	}

	if !v.ActiveType.Equal(other.ActiveType) {
		return false
	}

	if !v.Unhealthy.Equal(other.Unhealthy) {
		return false
	}

	return true
}

